mapper.update:
UPDATE sys_post post
SET post.deleted = 1,
    post.delete_by = #{scope.userId},
    post.delete_time = CURRENT_TIMESTAMP
WHERE post.id = #{postId}
  AND post.tenant_id = #{scope.tenantId}
  AND post.deleted = 0
  AND NOT EXISTS (
      SELECT 1 FROM sys_user_post binding
      WHERE binding.post_id = post.id
        AND binding.tenant_id = post.tenant_id
        AND binding.deleted = 0
  )

    AND (


            post.dept_id IN

                #{deptId}


                OR post.create_by = #{scope.userId}



            post.create_by = #{scope.userId}


            1 = 0


    )
